import React from 'react';

import { Flex } from '../../../../../layouts-core/flex/Flex.js';
import {
  BOTTOM_AXIS_LINE_OFFSET,
  Y_AXES_LINE_OFFSET,
} from '../../../constants.js';
import {
  MIN_AXIS_TRUNCATION_SIZE,
  X_AXES_LABEL_OFFSET,
  Y_AXIS_LABEL_OFFSET,
} from '../constants.js';

export interface DivAxisProps {
  children: React.ReactNode;
  ticks: string[];
  divAxisStyle?: object;
  label?: string;
  isTickVertical?: boolean;
  isTickRotated?: boolean;
}

const getDivContainerAxisStyle = (
  isTickVertical: boolean,
  isTickRotated: boolean,
) => {
  let tickStyle: React.CSSProperties;
  let labelStyle: React.CSSProperties;

  const rotatedTextStyle: React.CSSProperties = {
    writingMode: 'vertical-rl',
    textOrientation: 'upright',
  };

  if (isTickVertical) {
    tickStyle = {
      marginTop: BOTTOM_AXIS_LINE_OFFSET,
      minHeight: isTickRotated ? MIN_AXIS_TRUNCATION_SIZE : 0,
      whiteSpace: 'nowrap',
      overflow: 'hidden',
      ...(isTickRotated ? rotatedTextStyle : {}),
    };
    labelStyle = {
      marginTop: X_AXES_LABEL_OFFSET,
      whiteSpace: 'nowrap',
      overflow: 'hidden',
    };
  } else {
    tickStyle = {
      marginRight: Y_AXES_LINE_OFFSET,
      minWidth: MIN_AXIS_TRUNCATION_SIZE,
    };
    labelStyle = { marginRight: Y_AXIS_LABEL_OFFSET, ...rotatedTextStyle };
  }

  return { tickStyle, labelStyle };
};

/**
 * This component creates a layout containing an SVG and HTML version of the axis.
 * The SVG axis should be positioned absolutely within the wrapper component.
 * Below it, we need to generate an identical HTML axis with hidden visibility.
 * By doing this, we can obtain the size of the HTML axis and use it to dynamically position the SVG axis instead
 * of performing complex calculations. The HTML axis size allows us to use CSS Grid with a min-max content approach
 * and manage plots more efficiently.
 */
export const DivAxisWrapper = ({
  ticks,
  label,
  isTickVertical = false,
  isTickRotated = false,
  divAxisStyle = {},
  children,
}: DivAxisProps) => {
  const { tickStyle, labelStyle } = getDivContainerAxisStyle(
    isTickVertical,
    isTickRotated,
  );

  const containerAxisStyle: React.CSSProperties = { position: 'relative' };
  const visibleSvgAxisStyle: React.CSSProperties = {
    position: 'absolute',
  };
  const hiddenDivAxisStyle: React.CSSProperties = {
    visibility: 'hidden',
    ...divAxisStyle,
  };

  return (
    <div style={containerAxisStyle}>
      <div style={visibleSvgAxisStyle}>{children}</div>
      <Flex
        style={hiddenDivAxisStyle}
        flexDirection={isTickVertical ? 'column-reverse' : 'row'}
        gap={0}
      >
        {label && <span style={labelStyle}>{label}</span>}
        <Flex flexDirection={isTickVertical ? 'row' : 'column'}>
          {ticks?.map((tick, index) => (
            <span style={tickStyle} key={index + tick}>
              {tick}
            </span>
          ))}
        </Flex>
      </Flex>
    </div>
  );
};

DivAxisWrapper['displayName'] = 'DivAxisWrapper';
